import json

def get_table_data(title):
    node = node_by_title(doc, title)
    return table_rows(node)

task_log = get_table_data('Cell window 02: Task log')

# Find all tasks running on M02 at time 517
running_on_m02 = []
task_status = {} # task_id: (start_time, finish_time, machine)

# First pass: determine when tasks start and finish
for row_idx, row in task_log:
    t_id = row['task']
    event = row['event']
    time = int(row['time'])
    if event == 'start':
        task_status[t_id] = {'start': time, 'finish': None, 'machine': row['machine']}
    elif event == 'finish':
        if t_id in task_status:
            task_status[t_id]['finish'] = time
    elif event == 'evict' or event == 'fail':
        if t_id in task_status:
            task_status[t_id]['finish'] = time

# Second pass: check who is on M02 at time 517
for t_id, status in task_status.items():
    if status['machine'] == 'M02':
        start = status['start']
        finish = status['finish']
        # A task is running at time 517 if it started <= 517 and finished > 517
        # But wait, the events at time 517 happen in order.
        # We want to know who was there *before* the evictions at 517.
        if start <= 517 and (finish is None or finish >= 517):
            running_on_m02.append(t_id)

print(f"Tasks running on M02 around time 517: {running_on_m02}")

# Let's get their details
task_details = {}
for row_idx, row in task_log:
    if row['event'] == 'submit':
        task_details[row['task']] = row

for t_id in running_on_m02:
    print(f"{t_id}: {task_details.get(t_id)}")

