def find_tasks(window, task_ids):
    results = {}
    log_node = node_by_title(doc, f"{window}: Task log")
    if not log_node:
        return results

    rows = table_rows(log_node)
    for row_idx, row in rows:
        task_id = row['task']
        if task_id in task_ids:
            if task_id not in results:
                results[task_id] = []
            results[task_id].append(row)
    return results

