    tasks_running = collections.defaultdict(list) # machine -> [tasks]

    # We need to simulate the scheduling to be sure, but the task log tells us exactly what happened.
    # Let's just find all tasks that started and hadn't finished or been evicted by time_limit.

    tasks_status = {} # task_id -> {'machine': m, 'start': s, 'end': e, 'priority': p, 'cpu': c, 'mem': mem}

    for row in table_rows(task_log_node):
        r = row[1]
        t = int(r['time'])
        if t > time_limit:
            continue

        task_id = r['task']
        event = r['event']

        if event == 'start':
            tasks_status[task_id] = {'machine': r['machine'], 'start': t, 'end': None, 'priority': int(r['priority']), 'cpu': int(r['CPU']), 'mem': int(r['memory'])}
        elif event == 'finish':
            if task_id in tasks_status:
                tasks_status[task_id]['end'] = t
        elif event == 'evict' or event == 'fail':
            if task_id in tasks_status:
                tasks_status[task_id]['end'] = t

    running_at_t = collections.defaultdict(list)
    for tid, status in tasks_status.items():
        if status['start'] <= time_limit and (status['end'] is None or status['end'] > time_limit):
            running_at_t[status['machine']].append(tid)

    return running_at_t, tasks_status

