    machines = {}
    for idx, row in m_rows:
        machines[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory'])
        }

    # Queue at window end
    q_node = node_by_title(doc, "Cell window 23: Queue at window end")
    q_rows = table_rows(q_node)

    running = []
    waiting = []
    for idx, row in q_rows:
        task_data = {
            'task': row['task'],
            'priority': int(row['priority']),
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
        }
        if row.get('machine') and row['machine'] != '-':
            task_data['machine'] = row['machine']
            task_data['remaining'] = int(row['remaining'])
            running.append(task_data)
        else:
            waiting.append(task_data)

    # Need submit times for waiting tasks to resolve queue order (priority, then submit, then id)
    # Task log for submit times
    t_node = node_by_title(doc, "Cell window 23: Task log")
    t_rows = table_rows(t_node)
    submit_times = {}
    for idx, row in t_rows:
        if row['event'] == 'submit':
            submit_times[row['task']] = int(row['time'])

    for w in waiting:
        w['submit'] = submit_times.get(w['task'], 0)

    # Sort waiting tasks: priority (desc), submit (asc), id (asc)
    waiting.sort(key=lambda x: (-x['priority'], x['submit'], x['task']))

    return machines, running, waiting

