            'mem_free': int(m_row['memory']),
            'up': True
        }

    for row_idx, m_row in table_rows(m_node):
        fail_at = m_row['fails at']
        ret_at = m_row['returns at']
        m_id = m_row['machine']
        if fail_at != '-':
            f_time = int(fail_at)
            if f_time <= time:
                machines[m_id]['up'] = False
                if ret_at != '-' and int(ret_at) <= time:
                    machines[m_id]['up'] = True

    running_tasks = {}
    for row_idx, row in rows_log:
        t_time = int(row['time'])
        if t_time > time:
            break
        t_id = row['task']
        event = row['event']
        if event == 'start':
            running_tasks[t_id] = (row['machine'], int(row['CPU']), int(row['memory']))
        elif event in ['finish', 'evict', 'fail']:
            if t_id in running_tasks:
                del running_tasks[t_id]

    for m_id in machines:
        machines[m_id]['cpu_free'] = machines[m_id]['cpu_max']
        machines[m_id]['mem_free'] = machines[m_id]['mem_max']

    for t_id, (m_id, cpu, mem) in running_tasks.items():
        machines[m_id]['cpu_free'] -= cpu
        machines[m_id]['mem_free'] -= mem

    return machines, running_tasks

