node_queue = node_by_title(doc, 'Cell window 26: Queue at window end')
queue_rows = table_rows(node_queue)
running_at_1200 = {row['task'] for i, row in queue_rows}

waiting_at_1200 = []
for t, info in submitted.items():
    if t not in running_at_1200:
        # Also need to check if it finished before 1200
        # Let's check the log for 'finish' events.
        finished = False
        for j, row in log_rows:
            if row['task'] == t and row['event'] == 'finish':
                finished = True
                break
        if not finished:
            waiting_at_1200.append({'task': t, **info})

# Sort waiting tasks by priority (desc), then submission time (asc), then task id (asc)
# Actually, priority is higher = more important.
# Priority 0-11. Higher priority first.
waiting_at_1200.sort(key=lambda x: (-x['priority'], x['time'], x['task']))

