import collections

def get_task_data(window_id):
    # Find the task log table
    node = None
    for n in doc['nodes']:
        if n['title'] == f'Cell window {window_id}: Task log':
            node = n
            break

    if not node:
        return None

    rows = table_rows(node)
    tasks = {}
    for idx, row in rows:
        time = int(row['time'])
        task = row['task']
        job = row['job']
        priority = int(row['priority'])
        cpu = int(row['CPU'])
        mem = int(row['memory'])
        run_time = int(row['run time'])
        event = row['event']
        machine = row['machine']

        if task not in tasks:
            tasks[task] = {
                'job': job,
                'priority': priority,
                'cpu': cpu,
                'mem': mem,
                'run_time': run_time,
                'events': []
            }
        tasks[task]['events'].append((time, event, machine))
    return tasks

def get_machines_data(window_id):
    node = None
    for n in doc['nodes']:
        if n['title'] == f'Cell window {window_id}: Machines':
            node = n
            break

    rows = table_rows(node)
    machines = {}
    for idx, row in rows:
        m_id = row['machine']
        machines[m_id] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'fail': int(row['fails at']) if row['fails at'] != '-' else None,
            'return': int(row['returns at']) if row['returns at'] != '-' else None
        }
    return machines

